#!/bin/sh
# ==============================================================================
# atherBasic — Modern Emerald OpenWrt LuCI Theme Installer
# Single-command installation for OpenWrt 21.x, 22.x, 23.x, 24.x
# ==============================================================================

set -e

echo "=========================================================="
echo "  Installing atherBasic Modern Emerald Theme for LuCI     "
echo "=========================================================="

# 1. Create backup of original files
BACKUP_DIR="/root/theme_backup_original"
if [ ! -d "$BACKUP_DIR" ]; then
    echo "Creating backup of original theme in $BACKUP_DIR..."
    mkdir -p "$BACKUP_DIR/bootstrap" "$BACKUP_DIR/templates" "$BACKUP_DIR/dashboard"
    [ -d /www/luci-static/bootstrap ] && cp -r /www/luci-static/bootstrap "$BACKUP_DIR/" 2>/dev/null || true
    [ -d /usr/share/ucode/luci/template/themes/bootstrap ] && cp -r /usr/share/ucode/luci/template/themes/bootstrap "$BACKUP_DIR/templates/" 2>/dev/null || true
    [ -f /www/luci-static/resources/menu-bootstrap.js ] && cp /www/luci-static/resources/menu-bootstrap.js "$BACKUP_DIR/" 2>/dev/null || true
    [ -d /www/luci-static/resources/view/dashboard ] && cp -r /www/luci-static/resources/view/dashboard "$BACKUP_DIR/" 2>/dev/null || true
    echo "Backup completed successfully."
fi

# 2. Extract and install theme files
echo "Installing /www/luci-static/bootstrap/cascade.css..."
mkdir -p "$(dirname "/www/luci-static/bootstrap/cascade.css")"
cat << 'EOF_B64' | (base64 -d 2>/dev/null || openssl base64 -d 2>/dev/null || ucode -e 'import * as fs from "fs"; import { b64dec } from "luci.core"; let s = fs.readfile("/dev/stdin"); let f = fs.open("/www/luci-static/bootstrap/cascade.css", "w"); f.write(b64dec(s)); f.close();' 2>/dev/null) > "/www/luci-static/bootstrap/cascade.css"

EOF_B64

echo "Installing /www/luci-static/bootstrap/mobile.css..."
mkdir -p "$(dirname "/www/luci-static/bootstrap/mobile.css")"
cat << 'EOF_B64' | (base64 -d 2>/dev/null || openssl base64 -d 2>/dev/null || ucode -e 'import * as fs from "fs"; import { b64dec } from "luci.core"; let s = fs.readfile("/dev/stdin"); let f = fs.open("/www/luci-static/bootstrap/mobile.css", "w"); f.write(b64dec(s)); f.close();' 2>/dev/null) > "/www/luci-static/bootstrap/mobile.css"

EOF_B64

echo "Installing /www/luci-static/bootstrap/logo.svg..."
mkdir -p "$(dirname "/www/luci-static/bootstrap/logo.svg")"
cat << 'EOF_B64' | (base64 -d 2>/dev/null || openssl base64 -d 2>/dev/null || ucode -e 'import * as fs from "fs"; import { b64dec } from "luci.core"; let s = fs.readfile("/dev/stdin"); let f = fs.open("/www/luci-static/bootstrap/logo.svg", "w"); f.write(b64dec(s)); f.close();' 2>/dev/null) > "/www/luci-static/bootstrap/logo.svg"

EOF_B64

echo "Installing /www/luci-static/resources/menu-bootstrap.js..."
mkdir -p "$(dirname "/www/luci-static/resources/menu-bootstrap.js")"
cat << 'EOF_B64' | (base64 -d 2>/dev/null || openssl base64 -d 2>/dev/null || ucode -e 'import * as fs from "fs"; import { b64dec } from "luci.core"; let s = fs.readfile("/dev/stdin"); let f = fs.open("/www/luci-static/resources/menu-bootstrap.js", "w"); f.write(b64dec(s)); f.close();' 2>/dev/null) > "/www/luci-static/resources/menu-bootstrap.js"

EOF_B64

echo "Installing /www/luci-static/resources/view/dashboard/css/custom.css..."
mkdir -p "$(dirname "/www/luci-static/resources/view/dashboard/css/custom.css")"
cat << 'EOF_B64' | (base64 -d 2>/dev/null || openssl base64 -d 2>/dev/null || ucode -e 'import * as fs from "fs"; import { b64dec } from "luci.core"; let s = fs.readfile("/dev/stdin"); let f = fs.open("/www/luci-static/resources/view/dashboard/css/custom.css", "w"); f.write(b64dec(s)); f.close();' 2>/dev/null) > "/www/luci-static/resources/view/dashboard/css/custom.css"

EOF_B64

echo "Installing /www/luci-static/resources/view/dashboard/index.js..."
mkdir -p "$(dirname "/www/luci-static/resources/view/dashboard/index.js")"
cat << 'EOF_B64' | (base64 -d 2>/dev/null || openssl base64 -d 2>/dev/null || ucode -e 'import * as fs from "fs"; import { b64dec } from "luci.core"; let s = fs.readfile("/dev/stdin"); let f = fs.open("/www/luci-static/resources/view/dashboard/index.js", "w"); f.write(b64dec(s)); f.close();' 2>/dev/null) > "/www/luci-static/resources/view/dashboard/index.js"

EOF_B64

echo "Installing /usr/share/ucode/luci/template/themes/bootstrap/header.ut..."
mkdir -p "$(dirname "/usr/share/ucode/luci/template/themes/bootstrap/header.ut")"
cat << 'EOF_B64' | (base64 -d 2>/dev/null || openssl base64 -d 2>/dev/null || ucode -e 'import * as fs from "fs"; import { b64dec } from "luci.core"; let s = fs.readfile("/dev/stdin"); let f = fs.open("/usr/share/ucode/luci/template/themes/bootstrap/header.ut", "w"); f.write(b64dec(s)); f.close();' 2>/dev/null) > "/usr/share/ucode/luci/template/themes/bootstrap/header.ut"

EOF_B64

echo "Installing /usr/share/ucode/luci/template/themes/bootstrap/footer.ut..."
mkdir -p "$(dirname "/usr/share/ucode/luci/template/themes/bootstrap/footer.ut")"
cat << 'EOF_B64' | (base64 -d 2>/dev/null || openssl base64 -d 2>/dev/null || ucode -e 'import * as fs from "fs"; import { b64dec } from "luci.core"; let s = fs.readfile("/dev/stdin"); let f = fs.open("/usr/share/ucode/luci/template/themes/bootstrap/footer.ut", "w"); f.write(b64dec(s)); f.close();' 2>/dev/null) > "/usr/share/ucode/luci/template/themes/bootstrap/footer.ut"

EOF_B64

echo "Installing /www/luci-static/resources/view/dashboard/icons/internet.svg..."
mkdir -p "$(dirname "/www/luci-static/resources/view/dashboard/icons/internet.svg")"
cat << 'EOF_B64' | (base64 -d 2>/dev/null || openssl base64 -d 2>/dev/null || ucode -e 'import * as fs from "fs"; import { b64dec } from "luci.core"; let s = fs.readfile("/dev/stdin"); let f = fs.open("/www/luci-static/resources/view/dashboard/icons/internet.svg", "w"); f.write(b64dec(s)); f.close();' 2>/dev/null) > "/www/luci-static/resources/view/dashboard/icons/internet.svg"

EOF_B64

echo "Installing /www/luci-static/resources/view/dashboard/icons/not-internet.svg..."
mkdir -p "$(dirname "/www/luci-static/resources/view/dashboard/icons/not-internet.svg")"
cat << 'EOF_B64' | (base64 -d 2>/dev/null || openssl base64 -d 2>/dev/null || ucode -e 'import * as fs from "fs"; import { b64dec } from "luci.core"; let s = fs.readfile("/dev/stdin"); let f = fs.open("/www/luci-static/resources/view/dashboard/icons/not-internet.svg", "w"); f.write(b64dec(s)); f.close();' 2>/dev/null) > "/www/luci-static/resources/view/dashboard/icons/not-internet.svg"

EOF_B64

echo "Installing /www/luci-static/resources/view/dashboard/icons/router.svg..."
mkdir -p "$(dirname "/www/luci-static/resources/view/dashboard/icons/router.svg")"
cat << 'EOF_B64' | (base64 -d 2>/dev/null || openssl base64 -d 2>/dev/null || ucode -e 'import * as fs from "fs"; import { b64dec } from "luci.core"; let s = fs.readfile("/dev/stdin"); let f = fs.open("/www/luci-static/resources/view/dashboard/icons/router.svg", "w"); f.write(b64dec(s)); f.close();' 2>/dev/null) > "/www/luci-static/resources/view/dashboard/icons/router.svg"

EOF_B64

echo "Installing /www/luci-static/resources/view/dashboard/icons/devices.svg..."
mkdir -p "$(dirname "/www/luci-static/resources/view/dashboard/icons/devices.svg")"
cat << 'EOF_B64' | (base64 -d 2>/dev/null || openssl base64 -d 2>/dev/null || ucode -e 'import * as fs from "fs"; import { b64dec } from "luci.core"; let s = fs.readfile("/dev/stdin"); let f = fs.open("/www/luci-static/resources/view/dashboard/icons/devices.svg", "w"); f.write(b64dec(s)); f.close();' 2>/dev/null) > "/www/luci-static/resources/view/dashboard/icons/devices.svg"

EOF_B64

echo "Installing /www/luci-static/resources/view/dashboard/icons/wireless.svg..."
mkdir -p "$(dirname "/www/luci-static/resources/view/dashboard/icons/wireless.svg")"
cat << 'EOF_B64' | (base64 -d 2>/dev/null || openssl base64 -d 2>/dev/null || ucode -e 'import * as fs from "fs"; import { b64dec } from "luci.core"; let s = fs.readfile("/dev/stdin"); let f = fs.open("/www/luci-static/resources/view/dashboard/icons/wireless.svg", "w"); f.write(b64dec(s)); f.close();' 2>/dev/null) > "/www/luci-static/resources/view/dashboard/icons/wireless.svg"

EOF_B64

# 3. Configure LuCI Theme setting
echo "Configuring LuCI theme..."
uci set luci.main.mediaurlbase='/luci-static/bootstrap' 2>/dev/null || true
uci commit luci 2>/dev/null || true

# 4. Clear LuCI template and session caches
echo "Clearing LuCI template cache..."
rm -rf /tmp/luci-indexcache* /tmp/luci-modulecache* /tmp/luci-sessions* 2>/dev/null || true

echo "=========================================================="
echo "  atherBasic theme installed successfully!                "
echo "  Open http://$(uci get network.lan.ipaddr 2>/dev/null || echo '192.168.1.1') in your browser. "
echo "=========================================================="